"""Verifier for top-products-unit-share. Generated by scripts/build_harbor_tasks.py.

S1 cheap artifact checks, S2 content checks on the manifest of a re-run of
plot.py, S3 delivered PNG == fresh render, S5 sidecar against the answer key.
Machinery: verifier_core.py (adapted from harbor/example/tests/test_state.py).

Known blind spots (the point of the second mutant): nothing here measures
legibility -- tick-label rotation, overlap, clipping at the image edge, or
contrast -- and line dash patterns and legend placement are only partly checked.
"""

from pathlib import Path

import pytest

from verifier_core import (
    APP, DELIVERED_FIGURE, assert_close, axes, bar_containers, check_input_unchanged,
    check_rerender_matches, check_valid_nonblank_png, delivered, find_script, lines,
    load_sidecar, norm_colour, snapshot_delivered, reexecute,
)

INPUTS = {"transactions.csv": "6d300a4be1145cfead8ef172352cce983101409b2d2d87836d8cbc6042c4f74b"}


@pytest.fixture(scope="session")
def manifest():
    snapshot_delivered()
    return reexecute(Path("/tmp/reexec"))


def test_s1_figure_is_a_valid_nonblank_png():
    snapshot_delivered()
    check_valid_nonblank_png()


def test_s1_inputs_unchanged():
    for name, digest in INPUTS.items():
        check_input_unchanged(name, digest)


def test_s1_plotting_script_left_behind():
    assert find_script().stat().st_size > 0


def test_s3_delivered_png_matches_a_fresh_render(manifest):
    check_rerender_matches(manifest)


def png_size():
    from PIL import Image

    with Image.open(delivered(DELIVERED_FIGURE)) as image:
        return image.size

# total units per product / total units of ALL products * 100, top 8, largest first.
KEY = {"products": ["Atlas", "Beacon", "Delta", "Cobalt", "Ember", "Falcon", "Granite", "Harbor"], "share_pct": [14.577, 12.659, 12.095, 11.453, 9.819, 8.862, 7.037, 6.655]}
TOL = 0.05


def test_s5_sidecar_matches_key():
    declared = load_sidecar()
    assert sorted(declared) == ["products", "share_pct"], f"sidecar keys {sorted(declared)}"
    assert declared["products"] == KEY["products"], f"products {declared['products']}"
    assert_close(declared["share_pct"], KEY["share_pct"], TOL, "share_pct")


def _top_to_bottom(ax, offsets, values):
    """Bars in the order a reader sees them, top first, whichever way y runs."""
    pairs = sorted(zip(offsets, values))
    inverted = ax["ylim"][0] > ax["ylim"][1]
    return [v for _, v in (pairs if inverted else pairs[::-1])]


def test_s2_eight_horizontal_bars_sorted_largest_on_top(manifest):
    ax = axes(manifest)
    bars = [c for c in bar_containers(manifest) if c.get("orientation") == "horizontal"]
    assert bars, "no horizontal bars"
    offsets = [o for c in bars for o in c["offsets"]]
    values = [v for c in bars for v in c["values"]]
    assert_close(_top_to_bottom(ax, offsets, values), KEY["share_pct"], TOL, "bar lengths, top to bottom")
    labels = [t for t in ax["yticklabels"] if t.strip()]
    inverted = ax["ylim"][0] > ax["ylim"][1]
    shown = labels if inverted else labels[::-1]
    assert shown == KEY["products"], f"product labels top to bottom {shown}"


def test_s2_value_labels_with_one_decimal(manifest):
    texts = {str(a.get("text", "")).strip() for a in axes(manifest).get("annotations", [])}
    for value in KEY["share_pct"]:
        assert f"{value:.1f}%" in texts, f"no '{value:.1f}%' label on the chart"


def test_s2_axes_text_and_limits(manifest):
    ax = axes(manifest)
    assert ax["xlabel"] == "Share of all units sold (%)"
    assert ax["ylabel"] == "", f"unexpected y label {ax['ylabel']!r}"
    assert ax["title"] == "Top 8 products by unit share"
    assert abs(min(ax["xlim"])) < 1e-9, f"x axis starts at {min(ax['xlim'])}, not 0"
